function lsEsc(lsValue){return String(lsValue==null?'':lsValue).replace(/[&<>"']/g,lsChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[lsChar]));}
