function lsBadge(lsText,lsKind){return `<span class="badge b-${lsKind||(['通过','已关闭','已验证'].includes(lsText)?'ok':['失败','穿透','严重'].includes(lsText)?'danger':['等待','等待人','待确认关闭'].includes(lsText)?'warn':'info')}">${lsEsc(lsText)}</span>`;}
