function lsSelect(lsLabel,lsKey,lsOptions){return `<label class="stack small">${lsEsc(lsLabel)}<select style="min-height:44px;max-width:100%;background:var(--card);color:var(--fg)" onchange="lsSet('${lsKey}',this.value)">${lsOptions.map(lsOption=>{const lsPair=Array.isArray(lsOption)?lsOption:[lsOption,lsOption];return `<option value="${lsEsc(lsPair[0])}" ${lsState[lsKey]===lsPair[0]?'selected':''}>${lsEsc(lsPair[1])}</option>`;}).join('')}</select></label>`;}
