function lsRuns(){return WI.map(lsW=>{const lsF=lsRunFacts[lsW.id];if(lsF)return {...lsW,...lsF};const lsDone=lsW.s==='ACCEPTED';return {...lsW,state:lsDone?'通过':'等待',round:lsDone?1:0,stages:lsDone?['通过','通过','通过','通过','通过',lsW.l===4?'通过':'等待']:['等待','等待','等待','等待','等待','等待'],times:lsDone?['耗时未记录','耗时未记录','耗时未记录','耗时未记录','耗时未记录',lsW.l===4?'耗时未记录':'尚未开始']:Array(6).fill('尚未开始'),reason:lsW.block||(!lsDone?'尚未进入质量门；等待执行者提交声明与证据包。':''),inferred:true};});}
function lsStage(lsRun,lsIndex){const lsNames=['平台重跑','隐藏验收','测试 Agent','产品验收 Agent','人工评审（L3）','交付'];const lsS=lsRun.stages[lsIndex];return `<div class="stack" style="min-width:150px;flex:1;border:1px solid var(--border);border-radius:10px;padding:12px;gap:6px"><b class="small">${lsNames[lsIndex]}</b>${lsBadge(lsS,lsS==='跳过'?'stale':null)}<span class="muted small">${lsRun.times[lsIndex]}</span>${lsS==='失败'?lsLink(lsIndex===0&&lsRun.execution?'workspace/'+lsRun.execution:'workitem/'+lsRun.id,lsRun.reason||'查看失败原因'):''}</div>`;}
